            <div className={`modal ${active ? 'active' : ''}`}>
                <div className="modal-content">
                    <div id="Form_Heading">
                        <h1 id = "a123">Создание запроса</h1>
                        <h2 id = "a1233">Создайте запрос на нужный вам документ</h2>

                    </div>
                    <div id = "Frame71"> 
                        <imput/>
